// ═══ RACE 1: CHECK-THEN-ACT ═══
// Thread-1                          Thread-2
// if (balance >= 60000) (Recommended) if (balance >= 60000) (Recommended) (stale check!)
//   balance -= 60000                  balance -= 60000
// balance = 40000                   balance = -20000! OVERDRAFT!

class UnsafeAccount {
    int balance = 100000;
    void withdraw(int amount) {
        if (balance >= amount) {    // CHECK ← race window HERE!
            balance -= amount;       // ACT  ← another thread already changed balance!
        }
    }
}

// FIX: synchronized makes check+act ATOMIC
class SafeAccount {
    int balance = 100000;
    synchronized void withdraw(int amount) {
        if (balance >= amount) {    // CHECK
            balance -= amount;       // ACT
        }                            // Both inside ONE lock → atomic!
    }
}

// ═══ RACE 2: READ-MODIFY-WRITE (counter++) ═══
// counter = 0
// Thread-1: read(0) → increment → write(1)
// Thread-2: read(0) → increment → write(1)  (read STALE value!)
// Expected: 2. Actual: 1. One increment LOST!

// counter++ is NOT atomic! It's actually THREE operations:
// 1. Read counter from memory
// 2. Increment in register
// 3. Write back to memory
// Another thread can read between step 1 and 3!

// FIX: AtomicInteger (lock-free, CAS-based)
AtomicInteger counter = new AtomicInteger(0);
counter.incrementAndGet();  // atomic! Read-modify-write in ONE CAS operation!

// ═══ RACE 3: COMPOUND ACTION on collections ═══
Map<String, List<String>> map = new HashMap<>();
// Thread-1: if (!map.containsKey("SAV")) map.put("SAV", new ArrayList<>());
// Thread-2: if (!map.containsKey("SAV")) map.put("SAV", new ArrayList<>());
// Both threads create a new list → one overwrites the other!
// FIX: ConcurrentHashMap.computeIfAbsent("SAV", k -> new ArrayList<>());
