package com.bank.race;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class RaceConditionTest {

    // ═══ RACE: check-then-act (overdraft!) ═══
    static class UnsafeAccount {
        int balance;
        UnsafeAccount(int b) { balance = b; }
        void withdraw(int amount) {
            if (balance >= amount) {
                try { Thread.sleep(1); } catch (InterruptedException e) { }
                balance -= amount;
            }
        }
    }

    @Test
    void checkThenAct_raceCondition() throws InterruptedException {
        int overdrafts = 0;
        for (int trial = 0; trial < 50; trial++) {
            UnsafeAccount account = new UnsafeAccount(100);
            CountDownLatch latch = new CountDownLatch(2);

            new Thread(() -> { account.withdraw(70); latch.countDown(); }).start();
            new Thread(() -> { account.withdraw(70); latch.countDown(); }).start();
            latch.await();

            if (account.balance < 0) overdrafts++;
        }
        System.out.println("Overdrafts: " + overdrafts + "/50 trials");
        // Some trials will show negative balance → race condition!
    }

    // ═══ FIX: synchronized check-then-act ═══
    static class SafeAccount {
        int balance;
        SafeAccount(int b) { balance = b; }
        synchronized void withdraw(int amount) {
            if (balance >= amount) {
                balance -= amount;
            }
        }
    }

    @Test
    void synchronized_fixesCheckThenAct() throws InterruptedException {
        for (int trial = 0; trial < 100; trial++) {
            SafeAccount account = new SafeAccount(100);
            CountDownLatch latch = new CountDownLatch(2);

            new Thread(() -> { account.withdraw(70); latch.countDown(); }).start();
            new Thread(() -> { account.withdraw(70); latch.countDown(); }).start();
            latch.await();

            assertThat(account.balance).isGreaterThanOrEqualTo(0);  // NEVER negative!
        }
    }

    // ═══ RACE: read-modify-write (lost increment) ═══
    @Test
    void readModifyWrite_lostIncrement() throws InterruptedException {
        int[] counter = {0};
        int threads = 1000;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                counter[0]++;  // NOT atomic! race!
                latch.countDown();
            }).start();
        }
        latch.await();

        System.out.println("Expected: 1000, Actual: " + counter[0]);
        // Often less than 1000 — lost increments!
    }

    // ═══ FIX: AtomicInteger ═══
    @Test
    void atomicInteger_fixesReadModifyWrite() throws InterruptedException {
        AtomicInteger counter = new AtomicInteger(0);
        int threads = 1000;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                counter.incrementAndGet();  // atomic! CAS-based!
                latch.countDown();
            }).start();
        }
        latch.await();

        assertThat(counter.get()).isEqualTo(1000);  // ALWAYS 1000!
    }
}
